<?php
namespace App\Http\Controllers\Crm;
use App\Http\Controllers\Controller;use App\Models\{Customer,Product,Purchase};use Illuminate\Http\Request;
class PurchaseController extends Controller {private function auth(Request $r,Customer $c):void{abort_unless($r->user()->isCeo()||$c->branch_id===$r->user()->branch_id,403);}public function create(Request $r,Customer $customer){$this->auth($r,$customer);$products=Product::orderBy('name')->get();return view('crm.purchases.create',compact('customer','products'));}public function store(Request $r,Customer $customer){$this->auth($r,$customer);$d=$r->validate(['branch_id'=>'required|exists:branches,id','purchased_at'=>'required|date','notes'=>'nullable|string','items'=>'required|array|min:1','items.*.product_id'=>'nullable|exists:products,id','items.*.product_name'=>'required_without:items.*.product_id|nullable|string|max:150','items.*.imei'=>'nullable|string|max:50','items.*.qty'=>'required|integer|min:1','items.*.unit_price'=>'required|integer|min:0','items.*.warranty_type'=>'nullable|in:toko,resmi','items.*.warranty_until'=>'nullable|date']);$items=$d['items'];foreach($items as &$i){if(!empty($i['product_id']))$i['product_name']=Product::find($i['product_id'])->name;}$p=Purchase::record(['customer_id'=>$customer->id,'branch_id'=>$r->user()->isCeo()?$d['branch_id']:$r->user()->branch_id,'purchased_at'=>$d['purchased_at'],'notes'=>$d['notes']??null],$items,$r->user());return redirect()->route('crm.purchases.show',$p)->with('ok','Transaksi dicatat.');}public function show(Request $r,Purchase $purchase){$this->auth($r,$purchase->customer);$purchase->load(['customer','branch','servedBy','items.product','histories.user']);return view('crm.purchases.show',compact('purchase'));}}
